    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_rust_bridge_fn_free_anisetteclient(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_rust_bridge_fn_clone_anisetteclient(handle, status)
        }
    }

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeAnisetteClient: FfiConverter<AnisetteClient, Long> {
    override fun lower(value: AnisetteClient): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): AnisetteClient {
        return AnisetteClient(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): AnisetteClient {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: AnisetteClient) = 8UL

    override fun write(value: AnisetteClient, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


