/**
 * @suppress
 */
public object FfiConverterTypeQuickConnectChannel: FfiConverter<QuickConnectChannel, Long> {
    internal val handleMap = UniffiHandleMap<QuickConnectChannel>()

    override fun lower(value: QuickConnectChannel): Long {
        if (value is QuickConnectChannelImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): QuickConnectChannel {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return QuickConnectChannelImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): QuickConnectChannel {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: QuickConnectChannel) = 8UL

    override fun write(value: QuickConnectChannel, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


// This template implements a class for working with a Rust struct via a handle
