    var `latitude`: kotlin.Float
    , 
    var `longitude`: kotlin.Float
    , 
    var `horizontalAccuracy`: kotlin.UByte
    , 
    var `status`: kotlin.UByte
    , 
    var `confidence`: kotlin.UByte
    , 
    var `timestamp`: kotlin.Long
    , 
    var `keyIndex`: kotlin.ULong
    
