    override fun allocationSize(value: FmLocationReport) = (
            FfiConverterFloat.allocationSize(value.`latitude`) +
            FfiConverterFloat.allocationSize(value.`longitude`) +
            FfiConverterUByte.allocationSize(value.`horizontalAccuracy`) +
            FfiConverterUByte.allocationSize(value.`status`) +
