    , 
    var `locationLabel`: kotlin.String?
    , 
    var `locationLabelId`: kotlin.String?
    , 
    var `publishReason`: kotlin.UInt
    , 
    var `course`: kotlin.Double
    , 
    var `speed`: kotlin.Double
    , 
    var `motionActivityState`: kotlin.UInt
    
){
    

    

    
    companion object
}

