/**
 * `MMCS` carries every stored variant of the one attachment -- the same image at several
 * qualities, each its own MMCS file -- in whatever order the message listed them. Kotlin orders
 * them by size and takes the largest (`AttachmentType.Mmcs.largest`), which is also what
 * rustpush's own `Attachment::get_attachment` downloads.
 */
sealed class AttachmentType {
    
    data class Inline(
        val v1: kotlin.ByteArray) : AttachmentType()
        
    {
        

        companion object
    }
    
    data class Mmcs(
        val v1: List<uniffi.rust_bridge.MmcsFile>) : AttachmentType()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAttachmentType : FfiConverterRustBuffer<AttachmentType>{
    override fun read(buf: ByteBuffer): AttachmentType {
        return when(buf.getInt()) {
            1 -> AttachmentType.Inline(
                FfiConverterByteArray.read(buf),
                )
            2 -> AttachmentType.Mmcs(
                FfiConverterSequenceTypeMmcsFile.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AttachmentType): ULong = when(value) {
        is AttachmentType.Inline -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.v1)
            )
        }
        is AttachmentType.Mmcs -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeMmcsFile.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: AttachmentType, buf: ByteBuffer) {
        when(value) {
            is AttachmentType.Inline -> {
                buf.putInt(1)
                FfiConverterByteArray.write(value.v1, buf)
                Unit
            }
            is AttachmentType.Mmcs -> {
                buf.putInt(2)
                FfiConverterSequenceTypeMmcsFile.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





